import sys
from collections import deque

def solve():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        n = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]

    for i in range(1, n + 1):
        try:
            neighbors_str = next(iterator)
            if neighbors_str.strip() == "":
                continue
            neighbors = [int(x) for x in neighbors_str.split(',')]
            adj[i] = neighbors
        except StopIteration:
            break

    color = [-1] * (n + 1)
    count0 = 0
    count1 = 0

    for start_node in range(1, n + 1):
        if color[start_node] != -1:
            continue

        queue = deque([start_node])
        color[start_node] = 0
        c0 = 1
        c1 = 0

        while queue:
            u = queue.popleft()
            current_color = color[u]

            for v in adj[u]:
                if color[v] == -1:
                    new_color = 1 - current_color
                    color[v] = new_color
                    if new_color == 0:
                        c0 += 1
                    else:
                        c1 += 1
                    queue.append(v)

        count0 += c0
        count1 += c1

    result = (count0 * (count0 - 1)) // 2 + (count1 * (count1 - 1)) // 2
    print(result)

if __name__ == "__main__":
    solve()
